function escapeHtml(unsafe) {
    return unsafe
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

function get_welcome_message(username) {
    const safeUsername = escapeHtml(username);
    return `Welcome, ${safeUsername}!`;
}
```

